    "Сначала подготовьте стороннюю сторону, затем вернитесь и нажмите «Проверить и продолжить».",
  "bots.setup.callbackUrlTitle": "URL обратного вызова",
  "bots.setup.callbackUrlDescription.webhook":
    "Ваша внешняя система должна отправлять обратные вызовы входящих сообщений на этот адрес. Асинхронные исходящие ответы по-прежнему используют URL вебхука, указанный слева.",
  "bots.setup.callbackUrlDescription.webhookBind":
    "Привязка через вебхук использует тот же endpoint: отправьте сюда приватный запрос обратного вызова с text = /bind <код>.",
  "bots.setup.guide.telegram.create.1": "Откройте @BotFather в Telegram и создайте нового бота.",
  "bots.setup.guide.telegram.create.2":
    "Скопируйте токен HTTP API, который выдал BotFather, и вставьте его в эту форму.",
  "bots.setup.guide.telegram.create.3":
    "Удобно сразу открыть личный чат с ботом — команду привязки нужно отправить туда.",
  "bots.setup.guide.telegram.bind.1":
    "Вернитесь в Telegram и откройте личный чат с созданным ботом.",
  "bots.setup.guide.telegram.bind.2":
    "Если чат ещё не начат, нажмите Start или отправьте любое сообщение, затем отправьте {command}.",
  "bots.setup.guide.telegram.bind.3":
    "Вернитесь сюда после того, как Telegram подтвердит привязку.",
  "bots.setup.guide.weixin.create.1":
    "Запустите вход в Weixin по QR-коду, отсканируйте код в Weixin и подтвердите на телефоне.",
  "bots.setup.guide.weixin.create.2":
    "ZCode автоматически сохраняет bot_token, выданный iLink; после сканирования отправьте боту любое сообщение в Weixin, чтобы активировать чат.",
  "bots.setup.guide.weixin.create.3":
    "ZCode использует встроенный клиент iLink: `/ilink/bot/getupdates` для long polling и `/ilink/bot/sendmessage` для ответов.",
  "bots.setup.guide.weixin.bind.1": "Откройте личный чат Weixin, который нужно привязать.",
  "bots.setup.guide.weixin.bind.2": "Отправьте {command}.",
  "bots.setup.guide.weixin.bind.3":
    "Вернитесь сюда после привязки, чтобы задать рабочее пространство и CLI по умолчанию.",
  "bots.setup.guide.feishu.create.1":
    "Создайте собственное приложение в консоли разработчика Feishu/Lark и включите возможность бота.",
  "bots.setup.guide.feishu.create.2":
    "Скопируйте App ID и App Secret, затем включите события постоянного подключения для `im.message.receive_v1` и действий карточек.",
  "bots.setup.guide.feishu.create.3":
    "Выберите здесь нужный домен Feishu или Lark и вставьте учётные данные в форму.",
  "bots.setup.guide.feishu.bind.1":
    "Установите приложение в свой тенант и откройте личный чат с ботом.",
  "bots.setup.guide.feishu.bind.2": "Отправьте {command} в этом личном чате.",
  "bots.setup.guide.feishu.bind.3":
    "Вернитесь сюда после привязки, чтобы задать рабочее пространство и CLI по умолчанию.",
  "bots.setup.guide.webhook.create.1":
    "Режиму вебхука не нужен встроенный бот в стороннем продукте: вашей интеграции достаточно отправлять сообщения в ZCode методом POST.",
  "bots.setup.guide.webhook.create.2":
    "Сначала задайте общий секрет; добавьте и URL исходящего вебхука, если хотите получать асинхронные ответы.",
  "bots.setup.guide.webhook.create.3":
    "Используйте один постоянный userId для каждого внешнего пользователя, чтобы привязка и дальнейший контекст относились к одному человеку.",
  "bots.setup.guide.webhook.bind.1":
    "Отправьте POST-запрос обратного вызова личного сообщения на endpoint `/api/bots/webhook` в ZCode.",
  "bots.setup.guide.webhook.bind.2":
    'Payload должен содержать как минимум этот botId, постоянный userId, `chatType: "private"` и text, равный {command}.',
  "bots.setup.guide.webhook.bind.3":
    "Если бот использует секрет, передайте также `x-zcode-bot-secret`; после привязки вернитесь сюда.",
