  "settings.httpProxy": "HTTP-прокси",
  "settings.httpProxyDescription":
    "Направлять через этот прокси исходящий трафик моделей, MCP, командных инструментов и рендерера приложения; системные переменные окружения не читаются. Оставьте пустым для прямого подключения — встроенный браузер тогда использует системные настройки прокси. Перезапустите приложение, чтобы применить.",
