  "settings.modelProvider.fieldHelp": "О поле «{field}»",
  "settings.modelProvider.help.contextWindow":
    "Объём контекста, который модель обрабатывает за раз, в токенах. ZCode использует его для управления контекстом.\nНе превышайте фактический лимит модели.",
  "settings.modelProvider.help.maxOutputTokens":
    "Максимальное число токенов, которое может сгенерировать один запрос к модели.\nНе превышайте фактический лимит модели.",
  "settings.modelProvider.help.inputModalities":
    "Задайте типы содержимого, которые может принимать модель:\n\n- **Текст**: получает текст. Обязательно.\n- **Изображения**: получает изображения.\n- **Видео**: получает видео.\n- **PDF**: получает PDF-документы напрямую.",
  "settings.modelProvider.help.outputModalities":
    "Тип содержимого ответов модели. Сейчас поддерживается только текст.",
  "settings.modelProvider.help.capabilities":
    "- **Структурированный вывод**: поддержка ограничений JSON Schema на поля, типы и структуру вывода.\n- **Встроенный веб-поиск**: поддержка встроенного веб-поиска API модели.\n- **Системные сообщения посреди беседы**: поддержка вставки системных инструкций во время беседы.\n\nНе включайте возможности, которые модель не поддерживает.",
  "settings.modelProvider.help.reasoningLevelsOrdered":
    "Задайте уровни рассуждения, доступные в чате. **Они должны идти по возрастанию усилий рассуждения**.\nНе настраивайте уровни, которые модель не поддерживает.",
  "settings.modelProvider.help.reasoningLevelMapping":
    "С помощью выражения CEL сопоставьте текущий уровень рассуждения `reasoningLevel` с полями запроса к API модели. Возвращённый выражением JSON-объект объединяется с телом исходящего запроса.",
  "settings.modelProvider.help.advanced":
    "**Схема инструментов MFJS**: включает совместимость с Moonshot Flavored JSON Schema, которую обычно использует API модели Kimi от Moonshot. Включайте, только если API модели требует этот формат.",
  "settings.modelProvider.help.followRecommendedConfig":
    "Подбирает рекомендуемую конфигурацию по ID модели, базовому URL и формату API. ZCode постоянно обновляет рекомендации и автоматически синхронизирует их.\nЕсли вы меняете параметр вручную, он переходит в ручное управление и перестаёт следовать обновлениям рекомендаций; остальные параметры по-прежнему управляются умной настройкой.",
